-- rebuild; do not edit this file by hand.
--
-- Run once in the Supabase SQL Editor, after core-setup.sql and
-- community-social-setup.sql. Safe to rerun: every row has a fixed id and is
-- inserted with `on conflict do nothing`, so a rerun adds nothing twice and
-- leaves counters exact. Times are relative to now(), so the threads read as
-- recent on the day this runs.
--
-- 36 accounts, 50 posts, 738 comments, 1355 post reactions,
-- 2550 comment reactions, 280 follows. The accounts have no password and
-- cannot sign in. Their addresses use the reserved .invalid domain
-- (community-seed.calculixhub.invalid), so no mail is ever sent, and
-- community-seed-cleanup.sql removes all of it by that domain.
begin;

-- A learner who already holds one of these usernames would otherwise be the one
-- an @mention in the seed notifies. Stop instead.
do $$
declare
  taken text;
begin
  select string_agg(p.username, ', ') into taken
  from public.profiles p
  join auth.users u on u.id = p.id
  where lower(p.username) in ('minh_khoa_math', 'priya_sundar07', 'leo_hartmann', 'ananya_rk', 'jaden_okafor', 'sofia_marques_mt', 'hana_yoon22', 'ethan_caldwell9', 'linh_ngoc_tran', 'mateo_quispe', 'aisha_rahman_m', 'kuba_wisniewski', 'chloe_tanaka', 'bao_nguyen_17', 'omar_haddad_x', 'isla_mcbride', 'arjun_mehta_21', 'meilin_chen', 'noah_fischer_b', 'zeynep_aydin', 'gabriel_santos3', 'duc_anh_pham', 'emma_lindqvist', 'kofi_mensah_m', 'riya_kapoor5', 'sam_whitaker', 'yuki_morimoto', 'thao_vy_le', 'daniel_ivanov8', 'maya_goldberg', 'rafael_ortiz_v', 'farah_iqbal', 'quang_huy_do', 'nina_petrova', 'alex_chung_ca', 'gia_han_tran')
    and u.email not like '%@community-seed.calculixhub.invalid';
  if taken is not null then
    raise exception 'Community seed: these usernames already belong to learners: %. Rename the personas in scripts/community-seed/personas.mjs and rebuild.', taken;
  end if;
end $$;

